# Catechism bank — the manṣūbāt Q&A (research/sources/mensubat.txt, Ottoman script, items 1-15). Turkish transliterated into modern
# spelling; English a functional rendering; the Arabic definitions as the source vowels them (the Kāfiya's wording).
ITEMS = [
 {"n": 1, "q": {"tr": "«Mansûbât» ne kelimedir? Tarifi nedir? Mef'ûliyyet alâmetleri nelerdir?", "en": "What word is «manṣūbāt», how is it defined, and what are the signs of the object-role?"},
  "a": {"tr": "«Mansûb» kelimesinin cem'idir; mevsûfu müzekker gayr-i âkil olan sıfatlar elif ve tâ ile cem'lenir. Tarifi: mef'ûliyyet alâmetini taşıyan şey. Mef'ûliyyet alâmetleri: fetha, kesre, elif, yâ.",
        "en": "The plural of «manṣūb»; adjectives of non-rational masculine nouns take the alif-tāʾ plural. Definition: what carries the sign of the object-role. The signs: fatḥa, kasra, alif and yāʾ."},
  "ar": ["هُوَ مَا اشْتَمَلَ عَلَى عَلَمِ الْمَفْعُولِيَّةِ"], "notes": ["al-mansubat-al-maful-al-mutlaq", "tarifat-daftar-al-kafiya"]},
 {"n": 2, "q": {"tr": "Mef'ûl-i mutlak nedir? Kaç kısımdır?", "en": "What is the absolute object (mafʿūl muṭlaq), and how many kinds has it?"},
  "a": {"tr": "Zikredilen bir fiilin fâilinin, o fiilin mânâsı altında yaptığı şeyin adıdır. Üç kısımdır: te'kîdî — mânâsında fiilin mânâsı üzerine bir fazlalık yoksa (جَلَسْتُ جُلُوسًا); nev'î — fiilin bir nev'ine delâlet ederse (جَلَسْتُ جِلْسَةً); adedî — fiilin sayısına delâlet ederse (جَلَسْتُ جَلْسَةً).",
        "en": "The name of what the doer of a named verb did, under that verb's own meaning. Three kinds: of emphasis — adding nothing to the verb's meaning (جَلَسْتُ جُلُوسًا); of kind — naming a manner of the act (جَلَسْتُ جِلْسَةً); of number — counting the act (جَلَسْتُ جَلْسَةً)."},
  "ar": ["وَهُوَ اسْمُ مَا فَعَلَهُ فَاعِلُ فِعْلٍ مَذْكُورٍ بِمَعْنَاهُ", "جَلَسْتُ جُلُوسًا", "جَلَسْتُ جِلْسَةً", "جَلَسْتُ جَلْسَةً"], "notes": ["maful-mutlaq", "al-mansubat-al-maful-al-mutlaq"]},
 {"n": 3, "q": {"tr": "Mef'ûl-i mutlakın kısımlarından hangisi tesniye ve cem' olmaz? Niçin?", "en": "Which kind of absolute object takes no dual or plural, and why?"},
  "a": {"tr": "Te'kîdî olanı. Tesniye ve cem' sayıya delâlet edip taaddüd ister; te'kîdî mef'ûl-i mutlak ise sayıdan soyulmuş mâhiyete delâlet eder. Nev' ya da sayı kastedilirse tesniye ve cem' olabilir; aralarında zıtlık yoktur.",
        "en": "The one of emphasis. Dual and plural signify number and demand plurality, while the emphatic absolute object signifies the bare nature stripped of number. Where kind or number is meant, dual and plural are possible; there is no contradiction between them."},
  "ar": [], "notes": ["maful-mutlaq"]},
 {"n": 4, "q": {"tr": "Mef'ûl-i mutlak, fiilinin lafzından başka bir lafızla gelir mi?", "en": "May the absolute object come in a wording other than its verb's?"},
  "a": {"tr": "Gelebilir: ya madde bakımından (قَعَدْتُ جُلُوسًا) ya bâb bakımından (أَنْبَتَهُ اللهُ نَبَاتًا).",
        "en": "It may: differing in root (قَعَدْتُ جُلُوسًا) or in form (أَنْبَتَهُ اللهُ نَبَاتًا)."},
  "ar": ["قَعَدْتُ جُلُوسًا", "أَنْبَتَهُ اللهُ نَبَاتًا"], "notes": ["maful-mutlaq"]},
 {"n": 5, "q": {"tr": "Mecâzî mef'ûl-i mutlak nedir?", "en": "What is the figurative absolute object?"},
  "a": {"tr": "Hazfedilip sıfatı ya da muzâfun ileyhi yerine geçen mef'ûl-i mutlaktır. Sıfatın yerine geçtiğine misal: ضَرَبْتُ شَدِيدًا (aslı: ضَرَبْتُ ضَرْبًا شَدِيدًا); muzâfun ileyhin yerine geçtiğine misal: ضَرَبْتُ الْجَلَّادَ (aslı: ضَرَبْتُ ضَرْبَ الْجَلَّادِ).",
        "en": "An absolute object dropped and replaced by its adjective or its annexed-to noun. By the adjective: ضَرَبْتُ شَدِيدًا (for ضَرَبْتُ ضَرْبًا شَدِيدًا); by the annexed-to: ضَرَبْتُ الْجَلَّادَ (for ضَرَبْتُ ضَرْبَ الْجَلَّادِ)."},
  "ar": ["ضَرَبْتُ شَدِيدًا", "ضَرَبْتُ الْجَلَّادَ"], "notes": ["maful-mutlaq", "hadhf-al-mudaf-wal-mudaf-ilayh"]},
 {"n": 6, "q": {"tr": "Mef'ûl-i mutlakın fiili kaç şekilde hazfedilir?", "en": "In how many ways is the absolute object's verb dropped?"},
  "a": {"tr": "İki kısım: cevâzen ve vücûben. Vücûben hazif de ikidir: semâî ve kıyâsî.", "en": "Two: permittedly and obligatorily; obligatory dropping is again of two kinds, heard and regular."},
  "ar": [], "notes": ["maful-mutlaq", "hadhf-wa-taqdir"]},
 {"n": 7, "q": {"tr": "«خَيْرَ مَقْدَمٍ» neye misaldir?", "en": "What does «خَيْرَ مَقْدَمٍ» exemplify?"},
  "a": {"tr": "Mef'ûl-i mutlakın fiilinin cevâzen hazfine. Aslı: قَدِمْتَ قُدُومًا خَيْرَ مَقْدَمٍ. Mef'ûl-i mutlak olan قُدُومًا fiiliyle birlikte hazfedilip sıfatı خَيْرَ مَقْدَمٍ onun yerine geçmekle mecâzî mef'ûl-i mutlak da olmuştur.",
        "en": "The permitted dropping of the absolute object's verb. Its origin: قَدِمْتَ قُدُومًا خَيْرَ مَقْدَمٍ. The absolute object قُدُومًا went with its verb and its adjective خَيْرَ مَقْدَمٍ took its place — so it is a figurative absolute object as well."},
  "ar": ["قَدِمْتَ قُدُومًا خَيْرَ مَقْدَمٍ"], "notes": ["maful-mutlaq", "hadhf-wa-taqdir"]},
 {"n": 8, "q": {"tr": "Mef'ûl-i mutlakın fiilinin vücûben semâen hazfedildiği yerler kaçtır, nelerdir?", "en": "In how many heard cases must the absolute object's verb be dropped, and which are they?"},
  "a": {"tr": "Yedidir: سَقْيًا (سَقَاكَ اللهُ سَقْيًا)، رَعْيًا (رَعَاكَ اللهُ رَعْيًا)، خَيْبَةً (خَابَ خَيْبَةً)، جَدْعًا (جُدِعَ جَدْعًا)، حَمْدًا (حَمِدْتُ حَمْدًا)، شُكْرًا (شَكَرْتُ شُكْرًا)، عَجَبًا (عَجِبْتُ عَجَبًا).",
        "en": "Seven: سَقْيًا (for سَقَاكَ اللهُ سَقْيًا), رَعْيًا, خَيْبَةً, جَدْعًا, حَمْدًا, شُكْرًا, عَجَبًا — each the masdar left standing for a verb the Arabs never utter with it."},
  "ar": ["سَقْيًا، رَعْيًا، خَيْبَةً، جَدْعًا، حَمْدًا، شُكْرًا، عَجَبًا"], "notes": ["maful-mutlaq", "al-mansubat-al-maful-al-mutlaq"]},
 {"n": 9, "q": {"tr": "Mef'ûl-i mutlakın fiilinin vücûben kıyâsen hazfedildiği yerler kaçtır, nelerdir?", "en": "In how many regular cases must the absolute object's verb be dropped, and which are they?"},
  "a": {"tr": "Altıdır. 1) Haber olmayan bir isme giren nefiyden ya da nefiy mânâsından sonra müsbet gelirse, ya da o isimden sonra tekrarlanırsa: مَا أَنْتَ إِلَّا سَيْرًا، إِنَّمَا أَنْتَ سَيْرًا، زَيْدٌ سَيْرًا سَيْرًا. 2) Önceki cümlenin mânâsının eserini tafsil ederse: فَشُدُّوا الْوَثَاقَ فَإِمَّا مَنًّا بَعْدُ وَإِمَّا فِدَاءً. 3) Kendi mânâsında bir isim ve sahibini içeren cümleden sonra, organların fiillerinden bir fiile delâlet edecek şekilde teşbih gelirse: مَرَرْتُ بِزَيْدٍ فَإِذَا لَهُ صَوْتٌ صَوْتَ حِمَارٍ. 4) Başkasına ihtimali olmayan cümlenin mazmûnu olursa: عَلَيَّ أَلْفُ دِرْهَمٍ اعْتِرَافًا. 5) Başkasına ihtimali olan cümlenin mazmûnu olursa: زَيْدٌ قَائِمٌ حَقًّا. 6) Fâiline ya da mef'ûlüne muzâf tesniye olursa: لَبَّيْكَ، سَعْدَيْكَ.",
        "en": "Six. 1) After a negation (or its sense) over a noun that is not a predicate, an affirmed or repeated masdar: مَا أَنْتَ إِلَّا سَيْرًا، إِنَّمَا أَنْتَ سَيْرًا، زَيْدٌ سَيْرًا سَيْرًا. 2) Detailing the effect of the preceding sentence: فَشُدُّوا الْوَثَاقَ فَإِمَّا مَنًّا بَعْدُ وَإِمَّا فِدَاءً. 3) A likeness after a sentence holding a noun of its own meaning and its owner, where a bodily act is meant: مَرَرْتُ بِزَيْدٍ فَإِذَا لَهُ صَوْتٌ صَوْتَ حِمَارٍ. 4) The content of a sentence that admits nothing else: عَلَيَّ أَلْفُ دِرْهَمٍ اعْتِرَافًا. 5) The content of a sentence that admits something else: زَيْدٌ قَائِمٌ حَقًّا. 6) A dual annexed to its doer or object: لَبَّيْكَ، سَعْدَيْكَ."},
  "ar": ["مَا أَنْتَ إِلَّا سَيْرًا", "زَيْدٌ سَيْرًا سَيْرًا", "مَرَرْتُ بِزَيْدٍ فَإِذَا لَهُ صَوْتٌ صَوْتَ حِمَارٍ", "عَلَيَّ أَلْفُ دِرْهَمٍ اعْتِرَافًا", "زَيْدٌ قَائِمٌ حَقًّا", "لَبَّيْكَ وَسَعْدَيْكَ"], "notes": ["maful-mutlaq", "al-mansubat-al-maful-al-mutlaq", "hadhf-wa-taqdir"]},
 {"n": 10, "q": {"tr": "Mef'ûlün bihin tarifi nedir? Fiili üzerine takdimi câiz midir?", "en": "How is the direct object defined, and may it stand before its verb?"},
  "a": {"tr": "Fâilin fiilinin üzerine vâki olduğu şeydir. Fiili amelde kuvvetli olduğu için mef'ûlün bih önde de arkada da nasbedilir; takdimi câizdir: زَيْدًا ضَرَبْتُ. Takdim ikidir: cevâzen (اللهَ أَعْبُدُ) ve mef'ûlün bih şart ya da istifham mânâsı taşırsa vücûben (مَنْ رَأَيْتَ؟ مَنْ تُكْرِمْ يُكْرِمْكَ).",
        "en": "That upon which the doer's act falls. Its verb is strong enough to govern it before or after, so putting it first is allowed: زَيْدًا ضَرَبْتُ. Two cases: permitted (اللهَ أَعْبُدُ), and obligatory when the object carries a conditional or interrogative sense (مَنْ رَأَيْتَ؟ مَنْ تُكْرِمْ يُكْرِمْكَ)."},
  "ar": ["هُوَ مَا وَقَعَ عَلَيْهِ فِعْلُ الْفَاعِلِ", "زَيْدًا ضَرَبْتُ", "اللهَ أَعْبُدُ", "مَنْ تُكْرِمْ يُكْرِمْكَ"], "notes": ["maful-bihi", "al-maful-bihi-wa-qismah", "taqdim-al-musnad-ilayh"]},
 {"n": 11, "q": {"tr": "Mef'ûlün bihin fiili kaç şekilde hazfedilir?", "en": "In how many ways is the direct object's verb dropped?"},
  "a": {"tr": "İki: cevâzen (مَنْ أَضْرِبُ؟ diyene زَيْدًا demek — اِضْرِبْ hazfedilmiştir) ve vücûben, dört yerde: semâen, münâdâda, izmâr alâ şerîtati't-tefsîrde ve tahzîrde.",
        "en": "Two: permittedly (زَيْدًا in answer to مَنْ أَضْرِبُ؟, with اِضْرِبْ dropped) and obligatorily, in four places: the heard cases, the vocative, the verb implied on condition of explanation (ishtighāl), and the warning."},
  "ar": [], "notes": ["hadhf-al-maful", "al-maful-bihi-wa-qismah"]},
 {"n": 12, "q": {"tr": "Mef'ûlün bihin fiilinin vücûben semâen hazfi ne demektir? Misali nedir?", "en": "What is the heard obligatory dropping of the direct object's verb, and what are its examples?"},
  "a": {"tr": "Araplardan işitildiği gibi korunan hazif: Araplar nerede hazfetmişse orada hazfedilir, oraya kıyasla başka yerde hazfedilmez. Misaller: اِمْرَأً وَنَفْسَهُ (aslı اُتْرُكْ اِمْرَأً وَنَفْسَهُ), اِنْتَهُوا خَيْرًا لَكُمْ (aslı اِنْتَهُوا عَنِ التَّثْلِيثِ وَاقْصِدُوا خَيْرًا لَكُمْ), أَهْلًا وَسَهْلًا (aslı أَتَيْتَ أَهْلًا وَوَطِئْتَ سَهْلًا).",
        "en": "A dropping kept as the Arabs were heard to make it: where they dropped, one drops, and nowhere else by analogy. Examples: اِمْرَأً وَنَفْسَهُ (for اُتْرُكْ اِمْرَأً وَنَفْسَهُ), اِنْتَهُوا خَيْرًا لَكُمْ (for اِنْتَهُوا عَنِ التَّثْلِيثِ وَاقْصِدُوا خَيْرًا لَكُمْ), أَهْلًا وَسَهْلًا (for أَتَيْتَ أَهْلًا وَوَطِئْتَ سَهْلًا)."},
  "ar": ["اِمْرَأً وَنَفْسَهُ", "اِنْتَهُوا خَيْرًا لَكُمْ", "أَهْلًا وَسَهْلًا"], "notes": ["hadhf-al-maful"]},
 {"n": 13, "q": {"tr": "Münâdânın tarifi nedir? Nidâ harfleri nelerdir?", "en": "How is the vocative defined, and what are the letters of calling?"},
  "a": {"tr": "Lafzan ya da takdiren أَدْعُو yerine geçen bir harfle yönelmesi istenendir. Nidâ harfleri beştir: يَا، أَيَا، هَيَا، أَيْ ve hemze.",
        "en": "The one whose turning-to is sought by a letter standing, in wording or by estimation, for أَدْعُو. The letters are five: يَا، أَيَا، هَيَا، أَيْ and the hamza."},
  "ar": ["وَهُوَ الْمَطْلُوبُ إِقْبَالُهُ بِحَرْفٍ نَائِبٍ مَنَابَ أَدْعُو لَفْظًا أَوْ تَقْدِيرًا"], "notes": ["vocative-munada"]},
 {"n": 14, "q": {"tr": "Nidâ harfinin ve münâdânın lafzan ve takdiren olduğuna misal veriniz. İkbâl kaç kısımdır?", "en": "Give examples of the calling letter and the called one stated and implied. How many kinds has the turning-to (iqbāl)?"},
  "a": {"tr": "Harf lafzan: يَا زَيْدُ; harf takdiren: يُوسُفُ أَعْرِضْ عَنْ هَذَا (aslı يَا يُوسُفُ). Münâdâ lafzan: يَا زَيْدُ; münâdâ takdiren: أَلَا يَا اسْجُدُوا (aslı أَلَا يَا قَوْمُ اسْجُدُوا). İkbâl hakikaten olur (يَا زَيْدُ), hükmen olur (يَا سَمَاءُ، يَا جِبَالُ، يَا أَرْضُ).",
        "en": "Letter stated: يَا زَيْدُ; letter implied: يُوسُفُ أَعْرِضْ عَنْ هَذَا (for يَا يُوسُفُ). Called one stated: يَا زَيْدُ; implied: أَلَا يَا اسْجُدُوا (for أَلَا يَا قَوْمُ اسْجُدُوا). The turning-to is real (يَا زَيْدُ) or by ruling (يَا سَمَاءُ، يَا جِبَالُ، يَا أَرْضُ)."},
  "ar": ["يُوسُفُ أَعْرِضْ عَنْ هَذَا", "أَلَا يَا اسْجُدُوا"], "notes": ["vocative-munada", "hadhf-wa-taqdir"]},
 {"n": 15, "q": {"tr": "Münâdânın i'râb ve binâ hâlleri nasıldır?", "en": "How is the vocative declined or built?"},
  "a": {"tr": "1) Müfred (muzâf ve şibh-i muzâf olmayan) ma'rife ise ref' alâmeti üzere mebnîdir: يَا رَجُلُ، يَا زَيْدُ، يَا زَيْدَانِ، يَا زَيْدُونَ. 2) Başına lâm-ı istiğâse girerse mecrûr ve mu'rabdır: يَا لَزَيْدٍ. 3) Sonuna elif-i istiğâse gelirse fetha üzere mebnîdir: يَا زَيْدَاهُ. 4) Bunların dışında mansûbdur: يَا عَبْدَ اللهِ، يَا طَالِعًا جَبَلًا، يَا رَجُلًا (belirsiz birine hitapta).",
        "en": "1) A single definite (neither annexed nor annexation-like) is built on its rafʿ sign: يَا رَجُلُ، يَا زَيْدُ، يَا زَيْدَانِ، يَا زَيْدُونَ. 2) With the lām of appeal before it, it is declined in jarr: يَا لَزَيْدٍ. 3) With the alif of appeal after it, built on the fatḥa: يَا زَيْدَاهُ. 4) Otherwise it is in naṣb: يَا عَبْدَ اللهِ، يَا طَالِعًا جَبَلًا، يَا رَجُلًا (addressing no one in particular)."},
  "ar": ["يَا زَيْدُ", "يَا لَزَيْدٍ", "يَا زَيْدَاهُ", "يَا عَبْدَ اللهِ", "يَا طَالِعًا جَبَلًا"], "notes": ["vocative-munada", "al-mabni-ghayr-al-lazim-al-maqtu-an-al-idafa-wal-munada"]},
]
